class _FlashcardsPageState extends State<FlashcardsPage>{ int index=0; bool back=false; @override Widget build(BuildContext c){ final cards=AppState.instance.flashcards; if(cards.isEmpty)return Scaffold(appBar:AppBar(title:const Text('بطاقات المراجعة')),body:const Center(child:Text('لا توجد بطاقات بعد. أضف بطاقة من صفحة المساعد الذكي.'))); final Flashcard f=cards[index%cards.length]; return Scaffold(appBar:AppBar(title:const Text('بطاقات المراجعة')),body:Directionality(textDirection:TextDirection.rtl,child:Padding(padding:const EdgeInsets.all(20),child:Column(children:[Text('${index+1} / ${cards.length}',style:Theme.of(c).textTheme.titleMedium),const SizedBox(height:20),Expanded(child:GestureDetector(onTap:()=>setState(()=>back=!back),child:Card(child:Center(child:Padding(padding:const EdgeInsets.all(24),child:Text(back?f.back:f.front,textAlign:TextAlign.center,style:const TextStyle(fontSize:26,fontWeight:FontWeight.w800,height:1.5)))))),const SizedBox(height:12),Text(back?'الإجابة':'اضغط على البطاقة لإظهار الإجابة'),const SizedBox(height:12),Row(children:[Expanded(child:OutlinedButton(onPressed:(){AppState.instance.practiceFlashcard(f);setState((){index=(index-1+cards.length)%cards.length;back=false;});},child:const Text('راجع مرة أخرى'))),const SizedBox(width:10),Expanded(child:FilledButton(onPressed:(){AppState.instance.practiceFlashcard(f);setState((){index=(index+1)%cards.length;back=false;});},child:const Text('أتقنتها')))])])));}}
